import java.util.ArrayDeque;
import java.util.Deque;

public class Drill {
    static int bfs(char[][] g) {
        int R = g.length, C = g[0].length;
        boolean[][] seen = new boolean[R][C];
        Deque<int[]> q = new ArrayDeque<>();
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        @@BLANK@@
        seen[0][0] = true;
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            if (cur[0] == R - 1 && cur[1] == C - 1) return cur[2];
            for (int[] d : dirs) {
                int nr = cur[0] + d[0], nc = cur[1] + d[1];
                if (nr >= 0 && nr < R && nc >= 0 && nc < C && !seen[nr][nc] && g[nr][nc] != '#') {
                    seen[nr][nc] = true;
                    q.add(new int[]{nr, nc, cur[2] + 1});
                }
            }
        }
        return -1;
    }

    static int bad = 0;
    static void check(Object got, Object exp) {
        String g = String.valueOf(got), e = String.valueOf(exp);
        if (!g.equals(e)) { bad++; System.out.println("FAIL: got " + g + " expected " + e); }
    }
    static void done() { if (bad == 0) System.out.println("PASS"); }

    public static void main(String[] args) {
        check(bfs(new char[][]{"..#".toCharArray(), "#..".toCharArray(), "...".toCharArray()}), 4);
        check(bfs(new char[][]{".#".toCharArray(), "#.".toCharArray()}), -1);
        check(bfs(new char[][]{"..#".toCharArray(), "..#".toCharArray(), "##.".toCharArray()}), -1);
        done();
    }
}
